'use strict';
const M=MouldModel,$=id=>document.getElementById(id);
let jobs=[],selected=null,fetched=null,activeScript=null,timer=null,request=0,busy=false;
const time=d=>new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(d)+' IST';
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function notice(text,error=false){$('notice').replaceChildren();if(text)$('notice').append(el('p',text,error?'notice error':'notice'));}
function badge(value){const s=M.stage(value);let cls='grey';if(s==='IN PROCESS')cls='yellow';else if(s==='DONE'||s==='YES')cls='green';else if(s==='NOT APPLICABLE')cls='blue';else if(['NO','DELAY','DELAYED'].includes(s))cls='red';else if(s&&s!=='TO PLAN')cls='neutral';return el('span',value||'—','badge '+cls);}
function drawDirectory(){const q=$('jobSearch').value.toLowerCase(),list=$('jobs');list.replaceChildren();$('jobCount').textContent=jobs.length;for(const j of jobs.filter(j=>j.code.toLowerCase().includes(q))){const b=el('button',undefined,'job-item'+(j.id===selected?.id?' selected':''));b.setAttribute('aria-pressed',String(j.id===selected?.id));const top=el('span',undefined,'job-item-top');top.append(el('strong','Job '+j.name),el('small',j.customer));b.append(top,el('span',j.code,'job-code'),el('small',j.parts.length+' parts · '+j.received));b.addEventListener('click',()=>selectJob(j,true));list.append(b);}if(!list.children.length)list.append(el('p','No matching jobs.','muted'));}
function selectJob(j,push=false){selected=j;if(push){const u=new URL(location.href);u.searchParams.set('job',j.id);history.pushState({},'',u);$('partSearch').value='';$('statusFilter').value='all';}drawDirectory();$('loading').hidden=true;$('workspace').hidden=false;$('jobTitle').textContent='Job '+j.name;$('jobSerial').textContent=j.code;$('jobMeta').textContent='Customer '+j.customer+'  ·  Received '+j.received+'  ·  BOM '+(j.bom||'—')+'  ·  Trial (T0) '+(j.trial||'—');$('totalParts').textContent=j.parts.length;$('inProcess').textContent=j.parts.filter(M.isProcess).length;$('toPlan').textContent=j.parts.filter(M.isPlan).length;const ready=j.parts.filter(M.isReady).length;$('readyCount').textContent=ready+' / '+j.parts.length;$('readyText').textContent=ready===j.parts.length?'All part entries marked ready':(j.parts.length-ready)+' still to be marked ready';const remarks=[...new Set(j.parts.map(p=>p.remark.trim()).filter(Boolean))];$('remarksPanel').hidden=!remarks.length;$('mouldRemarks').textContent=remarks.join('\n\n');drawParts();}
function drawParts(){if(!selected)return;const q=$('partSearch').value.toLowerCase(),filter=$('statusFilter').value,pred={all:()=>true,process:M.isProcess,plan:M.isPlan,delay:M.isDelayed,ready:M.isReady}[filter];const rows=selected.parts.filter(p=>(p.name+' '+p.material+' '+p.vendors.join(' ')).toLowerCase().includes(q)&&pred(p));const body=$('parts');body.replaceChildren();for(const p of rows){const row=el('tr');row.append(el('th',p.name,'part-col'));row.firstChild.scope='row';row.append(el('td',p.qty||'—','qty'),el('td',p.material||'—'));const drawing=el('td');const tick=el('span',p.drawing?'✓':'—',p.drawing?'drawing ready':'drawing');tick.setAttribute('aria-label',p.drawing?'2D ready':'2D not ready');drawing.append(tick);row.append(drawing);for(let i=0;i<3;i++){row.append(el('td',p.vendors[i]||'—','vendor'));const c=el('td');c.append(badge(p.stages[i]));row.append(c);}const r=el('td');r.append(badge(p.ready));row.append(r,el('td',p.dispatch||'—'),el('td',p.due||'—'),el('td',p.remark||'—','remark-cell'));body.append(row);}if(!rows.length){const row=el('tr'),c=el('td','No parts match these filters.','empty');c.colSpan=14;row.append(c);body.append(row);}$('visibleCount').textContent=rows.length+' of '+selected.parts.length+' parts';}
function fail(message){busy=false;$('refresh').disabled=false;$('refresh').textContent='↻ Refresh';$('syncDot').classList.add('offline');$('syncText').textContent=fetched?'Last fetched '+time(fetched)+' · stale':'Sheet unavailable';notice(message+(fetched?' Showing previously fetched data; statuses may have changed.':''),true);if(!jobs.length){$('loading').hidden=false;$('loading').querySelector('h1').textContent='Unable to load the sheet';$('loading').querySelector('p').textContent='Use Refresh to try again. The source sheet must remain readable to the tracker.';const btn=el('button','Retry connection','primary');btn.addEventListener('click',load);if(!$('loading').querySelector('button'))$('loading').append(btn);}}
function load(){if(busy)return;busy=true;$('refresh').disabled=true;$('refresh').textContent='Refreshing…';const n=++request,callback='mouldSheetResponse'+n;if(activeScript)activeScript.remove();let done=false;const cleanup=()=>{clearTimeout(timer);if(activeScript)activeScript.remove();delete window[callback];};window[callback]=data=>{if(done)return;done=true;cleanup();try{if(data.status!=='ok')throw Error('Google Sheets could not return the records.');jobs=M.parse(data.table);fetched=new Date();$('syncText').textContent='Fetched '+time(fetched);$('syncDot').classList.remove('offline');notice('');const wanted=new URL(location.href).searchParams.get('job');const j=wanted?jobs.find(j=>j.id===M.key(wanted)):jobs[0];if(j)selectJob(j);else{$('workspace').hidden=true;$('loading').hidden=false;$('loading').querySelector('h1').textContent='Mould not found';$('loading').querySelector('p').textContent='This QR identifier is not in the sheet. Choose a mould from the directory or check its job/customer/received code.';drawDirectory();}busy=false;$('refresh').disabled=false;$('refresh').textContent='↻ Refresh';}catch(e){fail(e.message);}};activeScript=document.createElement('script');activeScript.src='https://docs.google.com/spreadsheets/d/1na81bDrcdb0SAaYOBLHKD-WGb1VvHUTbDImeoRl43Ug/gviz/tq?sheet=Sheet5&headers=2&tqx='+encodeURIComponent('out:json;responseHandler:'+callback)+'&_='+Date.now();activeScript.onerror=()=>{if(done)return;done=true;cleanup();fail('Could not reach Google Sheets. Please check the connection and sheet access.');};timer=setTimeout(()=>{if(done)return;done=true;cleanup();fail('Google Sheets took too long to respond. Please try Refresh.');},20000);document.head.append(activeScript);}
function mouldUrl(){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('job',selected.id);return u.href;}
$('jobSearch').addEventListener('input',drawDirectory);$('partSearch').addEventListener('input',drawParts);$('statusFilter').addEventListener('change',drawParts);$('refresh').addEventListener('click',load);
$('qrButton').addEventListener('click',()=>{const url=mouldUrl(),qr=qrcode(0,'M');qr.addData(url);qr.make();$('qrImage').innerHTML=qr.createSvgTag({cellSize:6,margin:24,scalable:true,alt:'QR for '+selected.code,title:'Scan for current mould status'});$('qrJob').textContent=selected.code;$('qrUrl').textContent=url;$('copyStatus').textContent='';$('qrDialog').showModal();});$('closeQr').addEventListener('click',()=>$('qrDialog').close());$('printQr').addEventListener('click',()=>window.print());$('copyLink').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(mouldUrl());$('copyStatus').textContent='Mould link copied.';}catch{$('copyStatus').textContent='Copy the link shown below the QR code.';}});
window.addEventListener('popstate',()=>{const wanted=new URL(location.href).searchParams.get('job'),j=wanted?jobs.find(j=>j.id===M.key(wanted)):jobs[0];if(j)selectJob(j);else{selected=null;$('workspace').hidden=true;notice('Mould not found. Choose a job from the directory.',true);drawDirectory();}});
load();setInterval(()=>{if(!document.hidden)load();},60000);
